<script setup lang="ts">import {ref,onMounted} from 'vue';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {createRun} from '../api/runs';import {useTask} from '../hooks/useTask';import {usePolling} from '../hooks/usePolling';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import RunTable from '../components/RunTable.vue';import {features} from '../constants/enums';const store=useResearch(),auth=useAuth(),name=ref('冬季复学 · 四维分群'),dataset=ref(0),selected=ref(Object.keys(features)),kmin=ref(2),kmax=ref(6),message=ref(''),{busy,error,perform}=useTask();onMounted(()=>perform(async()=>{await store.load();dataset.value=store.datasets[0]?.id||0;}));usePolling(async()=>{if(store.runs.some(r=>['queued','running'].includes(r.status)))await store.load();});function submit(){perform(async()=>{const run=await createRun({name:name.value,dataset_id:dataset.value,features:selected.value,k_min:kmin.value,k_max:kmax.value});message.value=`研究 #${run.id} 已进入计算队列。完成后从下方查看群组解释。`;await store.load();});}</script><template><PageHeading eyebrow="EXPERIMENT / FEATURE & MODEL CHOICE" title="让分群选择有据可查" description="标准化每个特征，比较候选 K 的轮廓系数。每次研究保留独立结果。"/><ErrorNotice :message="error" @retry="perform(store.load)"/><div class="experiment-layout"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><p class="eyebrow">NEW FIELD STUDY</p><h2>建立分群实验</h2><label>研究名称<input v-model="name" required minlength="2" maxlength="160"></label><label>观察数据集<select v-model="dataset"><option v-for="d in store.datasets" :value="d.id" :key="d.id">{{d.name}}</option></select></label><fieldset><legend>研究特征 <small>至少选择 2 项</small></legend><label v-for="(label,key) in features" :key="key" class="checkbox"><input v-model="selected" type="checkbox" :value="key">{{label}}</label></fieldset><div class="form-row"><label>K 下限<select v-model="kmin"><option v-for="k in [2,3,4,5,6]" :value="k">{{k}}</option></select></label><label>K 上限<select v-model="kmax"><option v-for="k in [2,3,4,5,6]" :value="k">{{k}}</option></select></label></div><button class="primary" :disabled="busy||selected.length<2||kmin>kmax">{{busy?'正在提交…':'提交到计算队列 →'}}</button><p v-if="message" class="success" role="status">{{message}}</p></form><section v-else class="research-form"><h2>当前为阅读权限</h2><p>你可以查看研究与下载已批准的匿名名单；新建研究需要研究员或负责人账号。</p></section><aside class="method-note"><span class="note-number">01 / METHOD</span><h2>先统一尺度，<br>再讨论距离。</h2><ol><li><b>Z-score 标准化</b><p>每一列减均值、除以标准差，避免金额量纲压过学习频次。</p></li><li><b>比较 K = 2…6</b><p>每个候选使用 KMeans，seed=42，10 次初始化。</p></li><li><b>以轮廓系数选优</b><p>s=(b−a)/max(a,b)，越接近 1 分离越清晰；同分选更小的 K。</p></li></ol><small>分群是观察工具，业务标签来自中心特征规则，不代表因果结论。</small></aside></div><section class="recent"><div class="section-title"><h2>所有研究 <small>队列状态自动刷新</small></h2></div><RunTable :runs="store.runs"/></section></template>
